// ============================================================================
// Dataset multidim methods
// ============================================================================

[[cpp11::register]]
SEXP GDAL7_dataset_get_root_group(SEXP xp) {
  GDALDatasetH* ptr = reinterpret_cast<GDALDatasetH*>(R_ExternalPtrAddr(xp));
  if (!ptr || !*ptr) {
    cpp11::stop("Invalid dataset handle");
  }

  GDALGroupH grp = GDALDatasetGetRootGroup(*ptr);
  if (!grp) {
    return R_NilValue;
  }

  // Group needs to be released with GDALGroupRelease
  return cpp11::external_pointer<GDALGroupH>(new GDALGroupH(grp));
}

