[[cpp11::register]]
cpp11::list GDAL7_mdarray_get_dimensions(SEXP xp) {
  GDALMDArrayH* ptr = reinterpret_cast<GDALMDArrayH*>(R_ExternalPtrAddr(xp));
  if (!ptr || !*ptr) {
    cpp11::stop("Invalid array handle");
  }

  size_t count = 0;
  GDALDimensionH* dims = GDALMDArrayGetDimensions(*ptr, &count);

  cpp11::writable::list result(count);
  cpp11::writable::strings names(count);
  cpp11::writable::doubles sizes(count);

  for (size_t i = 0; i < count; i++) {
    const char* name = GDALDimensionGetName(dims[i]);
    names[i] = name ? std::string(name) : std::string("");
    sizes[i] = static_cast<double>(GDALDimensionGetSize(dims[i]));
  }

  GDALReleaseDimensions(dims, count);

  result.push_back(cpp11::named_arg("name") = names);
  result.push_back(cpp11::named_arg("size") = sizes);

  return result;
}

